<section class="container section-top"><?php ff_heading('memberships','Your schedule. Your commitment. Find a package that fits.'); ?><div class="plan-grid"><?php foreach($plans??[] as $index=>$plan): ?><article class="plan-card <?=($plan['price']??0)==2000?'featured':''?>"><div><p class="eyebrow"><?=e(t($plan['kind']??'membership'))?></p><h2><?=e($plan['title'])?></h2><p class="plan-price"><?=e(str_replace(' MKD','',money($plan['price'])))?><span>MKD</span></p><p class="plan-description"><?=e($plan['description']??'')?></p><dl class="plan-facts"><div><dt><?=e(t('access_window'))?></dt><dd><?= !empty($plan['access_start'])?e(substr($plan['access_start'],0,5).'–'.substr($plan['access_end'],0,5)):e(t('unspecified')) ?></dd></div><div><dt><?=e(t('validity'))?></dt><dd><?=e($plan['duration_days']??'')?> <?=e(t('demo_days'))?></dd></div></dl><p class="fine-print"><?=e(t('Daily opening hours also apply. Exact business terms require confirmation.'))?></p></div><a class="button <?=($plan['price']??0)==2000?'':'secondary'?> full" href="<?=e(url('plan',['id'=>$plan['id']]))?>"><?=e(t('view_plan'))?> <?=ff_icon()?></a></article><?php endforeach ?></div><section class="section narrow-text"><h2><?=e(t('Know before you choose.'))?></h2><details class="faq-item"><summary><?=e(t('How do access windows work?'))?></summary><p><?=e(t('Access is limited by both the package window and published daily opening hours. Saturday begins no earlier than 08:00 and Sunday ends no later than 21:00. Day-session and tourist-pass windows and holiday exceptions are unspecified.'))?></p></details><details class="faq-item"><summary><?=e(t('Are classes or wellness included?'))?></summary><p><?=e(t('Real class and wellness inclusions are unconfirmed. The project gives active demo memberships access to fictional class reservations solely to demonstrate the workflow.'))?></p></details><details class="faq-item"><summary><?=e(t('Can I pay here?'))?></summary><p><?=e(t('No real payments are accepted. Checkout uses predefined demonstration scenarios, with no card or bank details.'))?></p></details></section></section>
